import { AppError } from '../errors.js';
import type { CaptionTrackInfo } from '../types.js';
import { request } from './http.js';
import { readText, type PlayerResponse } from './innertube.js';

export interface CaptionTrack extends CaptionTrackInfo {
  baseUrl: string;
}

export interface RawWord {
  /** Usually one word; occasionally a short multi-word segment such as "[ __ ]". */
  text: string;
  /** Start time in seconds. */
  time: number;
}

export interface RawCue {
  start: number;
  duration: number;
  text: string;
  /** Per-word timings. Only auto-generated tracks provide these. */
  words?: RawWord[];
}

/* ------------------------------------------------------------------ */
/* Track listing and selection                                         */
/* ------------------------------------------------------------------ */

/**
 * Caption URLs come from YouTube's response and are fetched by this server,
 * so only follow them when they really point at YouTube over HTTPS.
 */
function toYouTubeUrl(raw: string): string | null {
  try {
    const url = new URL(raw, 'https://www.youtube.com');
    const host = url.hostname.toLowerCase();
    const trusted = host === 'youtube.com' || host.endsWith('.youtube.com');
    return url.protocol === 'https:' && trusted ? url.toString() : null;
  } catch {
    return null;
  }
}

export function listCaptionTracks(player: PlayerResponse): CaptionTrack[] {
  const raw = player.captions?.playerCaptionsTracklistRenderer?.captionTracks ?? [];
  const tracks: CaptionTrack[] = [];
  const seen = new Set<string>();

  for (const track of raw) {
    if (!track.baseUrl || !track.languageCode) continue;
    const baseUrl = toYouTubeUrl(track.baseUrl);
    if (!baseUrl) continue;
    const isAutoGenerated = track.kind === 'asr';
    const id = track.vssId || `${isAutoGenerated ? 'a' : ''}.${track.languageCode}`;
    if (seen.has(id)) continue;
    seen.add(id);
    tracks.push({
      id,
      baseUrl,
      languageCode: track.languageCode,
      name: readText(track.name) || track.languageCode,
      isAutoGenerated,
    });
  }
  return tracks;
}

export function toTrackInfo(track: CaptionTrack): CaptionTrackInfo {
  return { id: track.id, languageCode: track.languageCode, name: track.name, isAutoGenerated: track.isAutoGenerated };
}

const primary = (code: string) => code.toLowerCase().split(/[-_]/)[0];

/**
 * Work out which language is actually spoken. Dubbed videos carry one audio
 * track per language (each with its own auto-generated captions), and YouTube
 * marks the original as the default audio track. Videos with a single audio
 * track have exactly one auto-generated caption track, in the spoken language.
 */
function spokenLanguage(tracks: CaptionTrack[], player: PlayerResponse): string | null {
  const tracklist = player.captions?.playerCaptionsTracklistRenderer;
  const originalAudio = tracklist?.audioTracks?.[tracklist.defaultAudioTrackIndex ?? 0];
  const fromAudio = originalAudio?.audioTrackId?.split('.')[0];
  if (fromAudio) return fromAudio;
  const auto = tracks.filter((t) => t.isAutoGenerated);
  return auto.length === 1 ? auto[0].languageCode : null;
}

/**
 * Choose the caption track to transcribe.
 *
 * With an explicit request, match the track id first, then the language code
 * (human-made captions before auto-generated ones). Without one, prefer the
 * spoken language: human-made captions in that language, then its
 * auto-generated track, then the creator's default track, then English.
 */
export function selectCaptionTrack(tracks: CaptionTrack[], player: PlayerResponse, requested?: string): CaptionTrack {
  if (tracks.length === 0) throw new AppError('NO_CAPTIONS');

  const manualFirst = [...tracks].sort((a, b) => Number(a.isAutoGenerated) - Number(b.isAutoGenerated));

  if (requested) {
    const wanted = requested.trim();
    const match =
      tracks.find((t) => t.id === wanted) ??
      manualFirst.find((t) => t.languageCode.toLowerCase() === wanted.toLowerCase()) ??
      manualFirst.find((t) => primary(t.languageCode) === primary(wanted));
    if (!match) {
      throw new AppError('LANGUAGE_UNAVAILABLE', {
        message: `Captions are not available in "${wanted}" for this video. Choose one of the available languages.`,
        availableLanguages: tracks.map(toTrackInfo),
      });
    }
    return match;
  }

  const spoken = spokenLanguage(tracks, player);
  if (spoken) {
    const inSpokenLanguage =
      manualFirst.find((t) => t.languageCode.toLowerCase() === spoken.toLowerCase()) ??
      manualFirst.find((t) => primary(t.languageCode) === primary(spoken));
    if (inSpokenLanguage) return inSpokenLanguage;
  }

  const tracklist = player.captions?.playerCaptionsTracklistRenderer;
  const audio = tracklist?.audioTracks?.[tracklist.defaultAudioTrackIndex ?? 0];
  const defaultRaw = tracklist?.captionTracks?.[audio?.defaultCaptionTrackIndex ?? -1];
  const creatorDefault = defaultRaw && tracks.find((t) => t.baseUrl === defaultRaw.baseUrl);

  return creatorDefault ?? manualFirst.find((t) => primary(t.languageCode) === 'en') ?? manualFirst[0];
}

/* ------------------------------------------------------------------ */
/* Text cleaning                                                       */
/* ------------------------------------------------------------------ */

const NAMED_ENTITIES: Record<string, string> = {
  amp: '&',
  lt: '<',
  gt: '>',
  quot: '"',
  apos: "'",
  nbsp: ' ',
};

export function decodeEntities(text: string): string {
  return text.replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (whole, entity: string) => {
    if (entity[0] === '#') {
      const code = entity[1] === 'x' || entity[1] === 'X' ? parseInt(entity.slice(2), 16) : parseInt(entity.slice(1), 10);
      return Number.isFinite(code) && code > 0 && code <= 0x10ffff ? String.fromCodePoint(code) : whole;
    }
    return NAMED_ENTITIES[entity.toLowerCase()] ?? whole;
  });
}

/**
 * Invisible characters that captions pick up from editors: zero-width space
 * and the left-to-right / right-to-left marks. Zero-width joiners are kept
 * because Indic and Persian text needs them to render correctly. (Line and
 * paragraph separators are whitespace and are collapsed with the rest.)
 */
const INVISIBLE = new RegExp(`[${[0x200b, 0x200e, 0x200f].map((code) => String.fromCharCode(code)).join('')}]`, 'g');

/** Turn raw caption text into a single clean line: no markup, entities, or stray whitespace. */
export function cleanCaptionText(raw: string): string {
  let text = raw;
  // Caption XML is frequently double-escaped (&amp;#39;), so decode twice.
  text = decodeEntities(decodeEntities(text));
  return text.replace(/<[^>]*>/g, '').replace(INVISIBLE, '').replace(/\s+/g, ' ').trim();
}

/* ------------------------------------------------------------------ */
/* Payload parsing                                                     */
/* ------------------------------------------------------------------ */

interface Json3Event {
  tStartMs?: number;
  dDurationMs?: number;
  segs?: { utf8?: string; tOffsetMs?: number }[];
}

/** Parse YouTube's `json3` timed-text format. */
export function parseJson3(body: string): RawCue[] {
  const data = JSON.parse(body) as { events?: Json3Event[] };
  if (!Array.isArray(data.events)) throw new Error('json3 payload has no events');

  const cues: RawCue[] = [];
  for (const event of data.events) {
    if (!event.segs || typeof event.tStartMs !== 'number') continue;
    const text = cleanCaptionText(event.segs.map((seg) => seg.utf8 ?? '').join(''));
    if (!text) continue;

    const startMs = event.tStartMs;
    // Auto-generated tracks carry one segment per word, each with its own offset.
    const hasWordTimings = event.segs.some((seg) => typeof seg.tOffsetMs === 'number');
    let words: RawWord[] | undefined;
    if (hasWordTimings) {
      words = [];
      for (const seg of event.segs) {
        const piece = cleanCaptionText(seg.utf8 ?? '');
        if (piece) words.push({ text: piece, time: (startMs + (seg.tOffsetMs ?? 0)) / 1000 });
      }
    }

    cues.push({ start: startMs / 1000, duration: Math.max(0, (event.dDurationMs ?? 0) / 1000), text, words });
  }
  return cues;
}

const attr = (attrs: string, name: string): number | null => {
  const match = new RegExp(`\\b${name}="([^"]*)"`).exec(attrs);
  if (!match) return null;
  const value = Number(match[1]);
  return Number.isFinite(value) ? value : null;
};

/** Parse both XML timed-text flavours: `<text start dur>` (seconds) and `<p t d>` (milliseconds). */
export function parseTimedTextXml(body: string): RawCue[] {
  const cues: RawCue[] = [];

  const legacy = /<text\b([^>]*)>([\s\S]*?)<\/text>/g;
  for (let match = legacy.exec(body); match; match = legacy.exec(body)) {
    const start = attr(match[1], 'start');
    const text = cleanCaptionText(match[2]);
    if (start === null || !text) continue;
    cues.push({ start, duration: attr(match[1], 'dur') ?? 0, text });
  }
  if (cues.length > 0) return cues;

  const srv3 = /<p\b([^>]*)>([\s\S]*?)<\/p>/g;
  for (let match = srv3.exec(body); match; match = srv3.exec(body)) {
    const start = attr(match[1], 't');
    const text = cleanCaptionText(match[2]);
    if (start === null || !text) continue;
    cues.push({ start: start / 1000, duration: (attr(match[1], 'd') ?? 0) / 1000, text });
  }
  return cues;
}

function withFormat(baseUrl: string, format: string | null): string {
  const url = new URL(baseUrl);
  if (format) url.searchParams.set('fmt', format);
  else url.searchParams.delete('fmt');
  return url.toString();
}

/**
 * Download and parse a caption track. `json3` is preferred because it includes
 * word-level timings for auto-generated captions; the XML format is the fallback.
 */
export async function fetchCaptionCues(track: CaptionTrack, userAgent: string, signal?: AbortSignal): Promise<RawCue[]> {
  const attempts: { format: string | null; parse: (body: string) => RawCue[] }[] = [
    { format: 'json3', parse: parseJson3 },
    { format: null, parse: parseTimedTextXml },
  ];

  let failure = 'The caption track could not be downloaded.';
  for (const { format, parse } of attempts) {
    const { status, body } = await request(withFormat(track.baseUrl, format), {
      headers: { 'User-Agent': userAgent, 'Accept-Language': 'en-US,en;q=0.9' },
      signal,
    });

    if (status === 429) throw new AppError('UPSTREAM_BLOCKED', { detail: 'YouTube answered with HTTP 429.' });
    if (status !== 200) {
      failure = `YouTube answered with HTTP ${status} for the caption track.`;
      continue;
    }
    if (!body.trim()) {
      failure = 'YouTube returned an empty caption track.';
      continue;
    }

    try {
      const cues = parse(body);
      if (cues.length > 0) return cues.sort((a, b) => a.start - b.start);
      failure = 'The caption track contains no text.';
    } catch {
      failure = 'The caption track was in a format that could not be read.';
    }
  }

  // Both formats came back readable but without any text: the track really is empty.
  if (failure === 'The caption track contains no text.') throw new AppError('EMPTY_TRANSCRIPT');
  throw new AppError('EXTRACTION_FAILED', { detail: failure });
}
